create table if not exists public.ai_project_settings (project_id uuid primary key references public.app_projects(id) on delete cascade, owner_token text not null, collection_enabled boolean not null default false, allowed_event_types text[] not null default '{}'::text[], retention_days integer not null default 365 check (retention_days between 1 and 3650), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.ai_events (id uuid primary key default gen_random_uuid(), owner_token text not null, project_id uuid not null references public.app_projects(id) on delete cascade, event_type text not null, source text not null default 'app', payload jsonb not null default '{}'::jsonb, occurred_at timestamptz not null default now(), created_at timestamptz not null default now());
create table if not exists public.ai_interactions (id uuid primary key default gen_random_uuid(), owner_token text not null, project_id uuid not null references public.app_projects(id) on delete cascade, input_text text not null, context jsonb not null default '{}'::jsonb, model text, response_text text, created_at timestamptz not null default now());
create table if not exists public.ai_feedback (id uuid primary key default gen_random_uuid(), owner_token text not null, project_id uuid not null references public.app_projects(id) on delete cascade, interaction_id uuid references public.ai_interactions(id) on delete cascade, accepted boolean, rating smallint, corrected_output jsonb, comment text, reviewed_by text, created_at timestamptz not null default now(), constraint ai_feedback_rating_range check (rating is null or rating between 1 and 5));
create table if not exists public.dataset_examples (id uuid primary key default gen_random_uuid(), owner_token text not null, project_id uuid not null references public.app_projects(id) on delete cascade, source_kind text not null, source_id uuid, input jsonb not null, output jsonb, metadata jsonb not null default '{}'::jsonb, status text not null default 'raw' check (status in ('raw','verified','training_ready','rejected')), quality_score numeric(5,2), verified_by text, verified_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint dataset_examples_quality_range check (quality_score is null or (quality_score >= 0 and quality_score <= 100)));
create table if not exists public.dataset_versions (id uuid primary key default gen_random_uuid(), owner_token text not null, project_id uuid not null references public.app_projects(id) on delete cascade, version integer not null, status text not null default 'ready' check (status in ('building','ready','failed')), example_count integer not null default 0, train_count integer not null default 0, validation_count integer not null default 0, manifest jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), unique(project_id, version));
create table if not exists public.dataset_version_items (dataset_version_id uuid not null references public.dataset_versions(id) on delete cascade, example_id uuid not null references public.dataset_examples(id) on delete restrict, split text not null check (split in ('train','validation')), ordinal integer not null, primary key (dataset_version_id, example_id), unique(dataset_version_id, ordinal));
create table if not exists public.dataset_exports (id uuid primary key default gen_random_uuid(), owner_token text not null, project_id uuid not null references public.app_projects(id) on delete cascade, dataset_version_id uuid not null references public.dataset_versions(id) on delete cascade, format text not null default 'zip' check (format in ('zip','jsonl','csv')), storage_path text, checksum_sha256 text, size_bytes bigint, status text not null default 'building' check (status in ('building','ready','failed')), error text, created_at timestamptz not null default now());
create index if not exists ai_events_owner_project_idx on public.ai_events(owner_token, project_id, occurred_at desc);
create index if not exists dataset_examples_owner_project_status_idx on public.dataset_examples(owner_token, project_id, status, created_at desc);
create index if not exists dataset_versions_owner_project_idx on public.dataset_versions(owner_token, project_id, version desc);
alter table public.ai_project_settings enable row level security; alter table public.ai_events enable row level security; alter table public.ai_interactions enable row level security; alter table public.ai_feedback enable row level security; alter table public.dataset_examples enable row level security; alter table public.dataset_versions enable row level security; alter table public.dataset_version_items enable row level security; alter table public.dataset_exports enable row level security;
grant all on public.ai_project_settings to service_role; grant all on public.ai_events to service_role; grant all on public.ai_interactions to service_role; grant all on public.ai_feedback to service_role; grant all on public.dataset_examples to service_role; grant all on public.dataset_versions to service_role; grant all on public.dataset_version_items to service_role; grant all on public.dataset_exports to service_role;
insert into storage.buckets (id, name, public, file_size_limit) values ('ai-dataset-exports', 'ai-dataset-exports', false, 104857600) on conflict (id) do update set public = false, file_size_limit = excluded.file_size_limit;
